using System.Text.Json;
using MySqlConnector;
using Npgsql;

namespace MeiErp.LegacyImport;

internal static class GatePassImporter
{
    private static readonly JsonSerializerOptions Json = new(){WriteIndented=true};
    internal sealed record Audit(DateTime Created,string? CreatedBy,DateTime? Modified,string? ModifiedBy,bool Deleted,DateTime? DeletedAt,string? DeletedBy);
    internal sealed record Pass(int Id,string Number,int Direction,int Status,string Person,string? Phone,string? Cnic,string? Company,string? Vehicle,string? Department,string Purpose,string? Notes,string? RefType,string? RefNumber,string AuthorizedId,string AuthorizedName,DateTime Issued,DateTime? Completed,string? CompletedBy,DateTime? Cancelled,string? CancelReason,bool Returnable,DateOnly? Due,DateTime? Returned,string? Received,Audit Audit);
    internal sealed record PassItem(int Id,int PassId,string Description,string? Serial,decimal Quantity,string? Unit,string? Remarks);
    internal sealed record Demo(int Id,string Number,int Status,string Customer,string? Phone,string? Reference,string? Department,string? Letter,DateTime Issued,string IssuerId,string IssuerName,DateOnly? Due,DateTime? Returned,string? Received,string? Condition,string? Notes,Audit Audit);
    internal sealed record DemoItem(int Id,int DemoId,string Description,string? Serial,decimal Quantity,string? Accessories,string? Remarks,DateTime? Returned);

    public static async Task<int> RunAsync(ImportOptions options,string password)
    {
        await using var source=new MySqlConnection($"Server={options.MySqlHost};Port={options.MySqlPort};Database=erp_gatepass;User ID={options.MySqlUser};Password={password};SslMode=Preferred");await source.OpenAsync();
        var passes=await ReadPasses(source);var passItems=await ReadPassItems(source);var demos=await ReadDemos(source);var demoItems=await ReadDemoItems(source);var errors=Validate(passes,passItems,demos,demoItems);
        Console.WriteLine(JsonSerializer.Serialize(new {Module="gatepass",options.Apply,Passes=passes.Count,PassItems=passItems.Count,Demos=demos.Count,DemoItems=demoItems.Count,Rejections=errors},Json));
        if(errors.Count>0){Console.Error.WriteLine("Validation rejected source rows; nothing was written.");return 2;}if(!options.Apply)return 0;
        var pg=Environment.GetEnvironmentVariable("MEIERP_DB_PASSWORD");if(string.IsNullOrEmpty(pg)){Console.Error.WriteLine("Set MEIERP_DB_PASSWORD for an apply run.");return 2;}
        await using var target=new NpgsqlConnection($"Host={options.PgHost};Port={options.PgPort};Database={options.PgDatabase};Username={options.PgUser};Password={pg}");await target.OpenAsync();await Apply(target,passes,passItems,demos,demoItems);Console.WriteLine("Gate Pass import committed and target counts reconciled.");return 0;
    }

    private static async Task<List<Pass>> ReadPasses(MySqlConnection db){const string q="SELECT Id,PassNumber,Direction,Status,PersonName,PersonPhone,PersonCnic,CompanyName,VehicleNumber,Department,Purpose,Notes,ReferenceType,ReferenceNumber,AuthorizedById,AuthorizedByName,IssuedAtUtc,CompletedAtUtc,CompletedByName,CancelledAtUtc,CancellationReason,IsReturnable,ExpectedReturnOn,ReturnedAtUtc,ReturnReceivedByName,CreatedAtUtc,CreatedBy,ModifiedAtUtc,ModifiedBy,IsDeleted,DeletedAtUtc,DeletedBy FROM GatePasses ORDER BY Id";await using var c=new MySqlCommand(q,db);await using var r=await c.ExecuteReaderAsync();var a=new List<Pass>();while(await r.ReadAsync())a.Add(new(r.GetInt32(0),r.GetString(1),r.GetInt32(2),r.GetInt32(3),r.GetString(4),S(r,5),S(r,6),S(r,7),S(r,8),S(r,9),r.GetString(10),S(r,11),S(r,12),S(r,13),r.GetString(14),r.GetString(15),r.GetDateTime(16),T(r,17),S(r,18),T(r,19),S(r,20),r.GetBoolean(21),D(r,22),T(r,23),S(r,24),AuditOf(r,25)));return a;}
    private static async Task<List<PassItem>> ReadPassItems(MySqlConnection db){const string q="SELECT Id,GatePassRecordId,Description,SerialNumber,Quantity,Unit,Remarks FROM GatePassItems ORDER BY Id";await using var c=new MySqlCommand(q,db);await using var r=await c.ExecuteReaderAsync();var a=new List<PassItem>();while(await r.ReadAsync())a.Add(new(r.GetInt32(0),r.GetInt32(1),r.GetString(2),S(r,3),r.GetDecimal(4),S(r,5),S(r,6)));return a;}
    private static async Task<List<Demo>> ReadDemos(MySqlConnection db){const string q="SELECT Id,IssuanceNumber,Status,CustomerName,CustomerPhone,CustomerReference,Department,ReferenceLetter,IssuedAtUtc,IssuedById,IssuedByName,ExpectedReturnOn,ReturnedAtUtc,ReceivedByName,ReturnCondition,Notes,CreatedAtUtc,CreatedBy,ModifiedAtUtc,ModifiedBy,IsDeleted,DeletedAtUtc,DeletedBy FROM DemoIssuances ORDER BY Id";await using var c=new MySqlCommand(q,db);await using var r=await c.ExecuteReaderAsync();var a=new List<Demo>();while(await r.ReadAsync())a.Add(new(r.GetInt32(0),r.GetString(1),r.GetInt32(2),r.GetString(3),S(r,4),S(r,5),S(r,6),S(r,7),r.GetDateTime(8),r.GetString(9),r.GetString(10),D(r,11),T(r,12),S(r,13),S(r,14),S(r,15),AuditOf(r,16)));return a;}
    private static async Task<List<DemoItem>> ReadDemoItems(MySqlConnection db){const string q="SELECT Id,DemoIssuanceId,Description,SerialNumber,Quantity,Accessories,Remarks,ReturnedAtUtc FROM DemoIssuanceItems ORDER BY Id";await using var c=new MySqlCommand(q,db);await using var r=await c.ExecuteReaderAsync();var a=new List<DemoItem>();while(await r.ReadAsync())a.Add(new(r.GetInt32(0),r.GetInt32(1),r.GetString(2),S(r,3),r.GetDecimal(4),S(r,5),S(r,6),T(r,7)));return a;}

    private static List<string> Validate(List<Pass> p,List<PassItem> pi,List<Demo> d,List<DemoItem> di){var e=new List<string>();var ids=p.Select(x=>x.Id).ToHashSet();var dids=d.Select(x=>x.Id).ToHashSet();foreach(var x in p){try{_ = GatePassMapping.Direction(x.Direction);_ = GatePassMapping.Status(x.Status);}catch(Exception ex){e.Add($"Pass {x.Id}: {ex.Message}");}if(string.IsNullOrWhiteSpace(x.Number)||string.IsNullOrWhiteSpace(x.Purpose))e.Add($"Pass {x.Id} lacks number or purpose.");}foreach(var x in pi){if(!ids.Contains(x.PassId))e.Add($"Pass item {x.Id} references missing pass {x.PassId}.");if(x.Quantity<=0)e.Add($"Pass item {x.Id} quantity must be positive.");}foreach(var x in d){try{_ = GatePassMapping.DemoStatus(x.Status);}catch(Exception ex){e.Add($"Demo {x.Id}: {ex.Message}");}if(string.IsNullOrWhiteSpace(x.Number)||string.IsNullOrWhiteSpace(x.Customer))e.Add($"Demo {x.Id} lacks number or customer.");}foreach(var x in di){if(!dids.Contains(x.DemoId))e.Add($"Demo item {x.Id} references missing issuance {x.DemoId}.");if(x.Quantity<=0)e.Add($"Demo item {x.Id} quantity must be positive.");}e.AddRange(p.GroupBy(x=>x.Number,StringComparer.OrdinalIgnoreCase).Where(x=>x.Count()>1).Select(x=>$"Duplicate pass number: {x.Key}"));e.AddRange(d.GroupBy(x=>x.Number,StringComparer.OrdinalIgnoreCase).Where(x=>x.Count()>1).Select(x=>$"Duplicate demo number: {x.Key}"));return e.Distinct().ToList();}

    private static async Task Apply(NpgsqlConnection db,List<Pass> p,List<PassItem> pi,List<Demo> d,List<DemoItem> di){await using var tx=await db.BeginTransactionAsync();await using(var count=new NpgsqlCommand("SELECT (SELECT COUNT(*) FROM gatepass.\"Passes\")+(SELECT COUNT(*) FROM gatepass.\"PassItems\")+(SELECT COUNT(*) FROM gatepass.\"DemoIssuances\")+(SELECT COUNT(*) FROM gatepass.\"DemoIssuanceItems\")",db,tx))if(Convert.ToInt64(await count.ExecuteScalarAsync())!=0)throw new InvalidOperationException("Gate Pass target is not empty.");foreach(var x in p)await Exec(db,tx,"INSERT INTO gatepass.\"Passes\" (\"Id\",\"Number\",\"Date\",\"Direction\",\"IsReturnable\",\"ExpectedBack\",\"PartyName\",\"PersonPhone\",\"PersonCnic\",\"CompanyName\",\"VehicleNumber\",\"Department\",\"Purpose\",\"Notes\",\"ReferenceType\",\"ReferenceNumber\",\"RaisedByUserId\",\"RaisedByName\",\"Status\",\"ClearedUtc\",\"ClearedByName\",\"CancelledUtc\",\"CancellationReason\",\"ReturnedUtc\",\"ReturnReceivedByName\",\"CreatedUtc\",\"CreatedBy\",\"ModifiedUtc\",\"ModifiedBy\",\"IsDeleted\",\"DeletedUtc\",\"DeletedBy\") VALUES (@id,@number,@date,@direction,@returnable,@due,@party,@phone,@cnic,@company,@vehicle,@department,@purpose,@notes,@refType,@refNumber,@raisedId,@raisedName,@status,@cleared,@clearedBy,@cancelled,@reason,@returned,@received,@created,@createdBy,@modified,@modifiedBy,@deleted,@deletedAt,@deletedBy)",("id",x.Id),("number",x.Number),("date",DateOnly.FromDateTime(x.Issued)),("direction",GatePassMapping.Direction(x.Direction)),("returnable",x.Returnable),("due",x.Due),("party",x.Company??x.Person),("phone",x.Phone),("cnic",x.Cnic),("company",x.Company),("vehicle",x.Vehicle),("department",x.Department),("purpose",x.Purpose),("notes",x.Notes),("refType",x.RefType),("refNumber",x.RefNumber),("raisedId",x.AuthorizedId),("raisedName",x.AuthorizedName),("status",GatePassMapping.Status(x.Status)),("cleared",Utc(x.Completed)),("clearedBy",x.CompletedBy),("cancelled",Utc(x.Cancelled)),("reason",x.CancelReason),("returned",Utc(x.Returned)),("received",x.Received),AuditArgs(x.Audit));foreach(var x in pi)await Exec(db,tx,"INSERT INTO gatepass.\"PassItems\" (\"Id\",\"PassId\",\"Description\",\"Quantity\",\"Unit\",\"SerialNumber\",\"Remarks\",\"ReturnedQuantity\") VALUES (@id,@pass,@description,@quantity,@unit,@serial,@remarks,@returned)",("id",x.Id),("pass",x.PassId),("description",x.Description),("quantity",x.Quantity),("unit",x.Unit??"each"),("serial",x.Serial),("remarks",x.Remarks),("returned",GatePassMapping.ReturnedQuantity(p.First(y=>y.Id==x.PassId).Status,x.Quantity)));foreach(var x in d)await Exec(db,tx,"INSERT INTO gatepass.\"DemoIssuances\" (\"Id\",\"Number\",\"Status\",\"CustomerName\",\"CustomerPhone\",\"CustomerReference\",\"Department\",\"ReferenceLetter\",\"IssuedUtc\",\"IssuedByUserId\",\"IssuedByName\",\"ExpectedReturnOn\",\"ReturnedUtc\",\"ReceivedByName\",\"ReturnCondition\",\"Notes\",\"CreatedUtc\",\"CreatedBy\",\"ModifiedUtc\",\"ModifiedBy\",\"IsDeleted\",\"DeletedUtc\",\"DeletedBy\") VALUES (@id,@number,@status,@customer,@phone,@reference,@department,@letter,@issued,@issuerId,@issuerName,@due,@returned,@received,@condition,@notes,@created,@createdBy,@modified,@modifiedBy,@deleted,@deletedAt,@deletedBy)",("id",x.Id),("number",x.Number),("status",GatePassMapping.DemoStatus(x.Status)),("customer",x.Customer),("phone",x.Phone),("reference",x.Reference),("department",x.Department),("letter",x.Letter),("issued",Utc(x.Issued)),("issuerId",x.IssuerId),("issuerName",x.IssuerName),("due",x.Due),("returned",Utc(x.Returned)),("received",x.Received),("condition",x.Condition),("notes",x.Notes),AuditArgs(x.Audit));foreach(var x in di)await Exec(db,tx,"INSERT INTO gatepass.\"DemoIssuanceItems\" (\"Id\",\"DemoIssuanceId\",\"Description\",\"SerialNumber\",\"Quantity\",\"Accessories\",\"Remarks\",\"ReturnedUtc\") VALUES (@id,@demo,@description,@serial,@quantity,@accessories,@remarks,@returned)",("id",x.Id),("demo",x.DemoId),("description",x.Description),("serial",x.Serial),("quantity",x.Quantity),("accessories",x.Accessories),("remarks",x.Remarks),("returned",Utc(x.Returned)));foreach(var t in new[]{"Passes","PassItems","DemoIssuances","DemoIssuanceItems"})await Exec(db,tx,$"SELECT setval(pg_get_serial_sequence('gatepass.\"{t}\"','Id'),GREATEST(COALESCE((SELECT MAX(\"Id\") FROM gatepass.\"{t}\"),1),1),true)");await using var check=new NpgsqlCommand("SELECT COUNT(*) FROM gatepass.\"Passes\"",db,tx);if(Convert.ToInt64(await check.ExecuteScalarAsync())!=p.Count)throw new InvalidOperationException("Gate Pass count reconciliation failed.");await tx.CommitAsync();}
    private static async Task Exec(NpgsqlConnection db,NpgsqlTransaction tx,string sql,params object[] args){await using var c=new NpgsqlCommand(sql,db,tx);foreach(var item in args){if(item is System.Runtime.CompilerServices.ITuple t&&t.Length==2&&t[0] is string n)c.Parameters.AddWithValue(n,t[1]??DBNull.Value);else if(item is (string,object?)[] a)foreach(var q in a)c.Parameters.AddWithValue(q.Item1,q.Item2??DBNull.Value);}await c.ExecuteNonQueryAsync();}
    private static (string,object?)[] AuditArgs(Audit a)=>[("created",Utc(a.Created)),("createdBy",a.CreatedBy),("modified",Utc(a.Modified)),("modifiedBy",a.ModifiedBy),("deleted",a.Deleted),("deletedAt",Utc(a.DeletedAt)),("deletedBy",a.DeletedBy)];
    private static Audit AuditOf(MySqlDataReader r,int i)=>new(r.GetDateTime(i),S(r,i+1),T(r,i+2),S(r,i+3),r.GetBoolean(i+4),T(r,i+5),S(r,i+6));private static string? S(MySqlDataReader r,int i)=>r.IsDBNull(i)?null:r.GetString(i);private static DateTime? T(MySqlDataReader r,int i)=>r.IsDBNull(i)?null:r.GetDateTime(i);private static DateOnly? D(MySqlDataReader r,int i)=>r.IsDBNull(i)?null:DateOnly.FromDateTime(r.GetDateTime(i));private static DateTime? Utc(DateTime? x)=>x is null?null:AutoMapping.Utc(x.Value);private static DateTime Utc(DateTime x)=>AutoMapping.Utc(x);
}
